import math
L=2.75
X=0.0;Y=0.0;TH=0.0;last_t=None
pts={}
corn=[]
phase='REV'
ef=0.0
woken=set()
lastp=-10

def clamp(a,lo,hi):
    return lo if a<lo else hi if a>hi else a

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def tow(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+px*c-py*s, Y+px*s+py*c)

def addcorner(wx,wy):
    for cl in corn:
        if math.hypot(cl[0]-wx,cl[1]-wy)<0.8:
            n=cl[2]
            cl[0]=(cl[0]*n+wx)/(n+1);cl[1]=(cl[1]*n+wy)/(n+1);cl[2]=min(n+1,30)
            return
    corn.append([wx,wy,1])

def control(obs):
    global X,Y,TH,last_t,phase,ef,lastp
    t=obs['t']
    mo=obs['motion'];v=mo['v_mps'];st=math.radians(obs['steer_deg'])
    if last_t is not None:
        dt=max(0.0,min(0.3,t-last_t))
        X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt;TH+=v/L*math.tan(st)*dt
    last_t=t
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        try:
            ox,oy=vw['origin']
        except Exception:
            continue
        for w in vw.get('walls',[]) or []:
            try:
                b=math.radians(w[0]);d=w[1]
            except Exception:
                continue
            wx,wy=tow(ox+d*math.cos(b),oy+d*math.sin(b))
            pts[(round(wx/0.15),round(wy/0.15))]=(wx,wy)
        for c in vw.get('target_corners',[]) or []:
            try:
                b=math.radians(c[0]);d=c[1]
            except Exception:
                continue
            wx,wy=tow(ox+d*math.cos(b),oy+d*math.sin(b))
            addcorner(wx,wy)
    rig=obs['rig']
    h=obs['hitch_deg']
    rx,ry=rig['trailer_rear']
    Rx,Ry=tow(rx,ry)
    thb=TH+math.radians(180-h)
    hw=rig.get('trailer_half_width',0.85)+0.25
    near=[p for p in pts.values() if abs(p[0]-Rx)<11 and abs(p[1]-Ry)<11]
    def free(phi,w,m=7.0):
        ux=math.cos(phi);uy=math.sin(phi)
        for px,py in near:
            ax=px-Rx;ay=py-Ry
            s=ax*ux+ay*uy
            if s<=0 or s>=m: continue
            d=-ax*uy+ay*ux
            if abs(d)<w: m=s
        return m
    fs=free(thb,hw)
    mode='open'
    big=sorted(corn,key=lambda c:-c[2])[:4]
    big=[c for c in big if c[2]>=2]
    e=None
    if len(big)==4:
        cx=sum(c[0] for c in big)/4;cy=sum(c[1] for c in big)/4
        sxx=sum((c[0]-cx)**2 for c in big);syy=sum((c[1]-cy)**2 for c in big);sxy=sum((c[0]-cx)*(c[1]-cy) for c in big)
        ang=0.5*math.atan2(2*sxy,sxx-syy)
        ax_=math.cos(ang);ay_=math.sin(ang)
        if ax_*math.cos(thb)+ay_*math.sin(thb)<0:
            ang+=math.pi;ax_=-ax_;ay_=-ay_
        if abs(wrap(math.degrees(ang-thb)))<70:
            lat=-(Rx-cx)*ay_+(Ry-cy)*ax_
            des=ang-math.atan2(lat,2.0)
            e=wrap(math.degrees(des-thb));mode='bay4'
    if e is None:
        tg=obs.get('target') or {}
        if tg.get('in_sight') and tg.get('dist_m') is not None:
            ex,ey=rig['eye'];b=math.radians(tg['bearing_deg']);d=tg['dist_m']
            tx,ty=tow(ex+d*math.cos(b),ey+d*math.sin(b))
            dd=math.hypot(tx-Rx,ty-Ry)
            if dd<9 and (tx-Rx)*math.cos(thb)+(ty-Ry)*math.sin(thb)>0:
                if dd>1.5:
                    e=wrap(math.degrees(math.atan2(ty-Ry,tx-Rx)-thb))
                else:
                    e=0.0
                mode='target'
    if e is None:
        best=None;be=0
        for off in range(-60,65,5):
            f=free(thb+math.radians(off),hw)
            sc=f-0.025*abs(off)
            if best is None or sc>best:
                best=sc;be=off
        e=float(be)
        # centering
        ux=math.cos(thb);uy=math.sin(thb);dl=9;dr=9
        for px,py in near:
            ax=px-Rx;ay=py-Ry
            s=ax*ux+ay*uy
            if -2.5<s<0.8:
                d=-ax*uy+ay*ux
                if d>0: dl=min(dl,d)
                else: dr=min(dr,-d)
        if dl<3 and dr<3:
            e+=clamp(10*(dl-dr),-12,12)
    ef=0.6*ef+0.4*e
    hdes=clamp(-1.2*ef,-28,28)
    if abs(h)>42 and phase=='REV':
        phase='FWD'
    if phase=='FWD':
        if abs(h)<8: phase='REV'
        else:
            return (0.0,0.8,-23)
    steer=clamp(0.75*hdes+2.0*(h-hdes),-34,34)
    spd=-min(1.0,max(0.3,0.4*fs))
    if abs(h-hdes)>15: spd=max(spd,-0.6)
    if fs<0.35:
        spd=0.0
        if 'wall' not in woken:
            woken.add('wall');wake('blocked behind fs=%.2f mode=%s h=%.1f'%(fs,mode,h))
    if t-lastp>2:
        lastp=t
        print('t=%.1f mode=%s e=%.0f hdes=%.0f h=%.1f fs=%.1f corners=%d'%(t,mode,ef,hdes,h,fs,len(big)))
    return (steer,spd,-23)

