import math
pose=[0.0,0.0,0.0]
pts={}
mode='rev'
phi_f=None
look=155.0
look_t=0.0
cnt=0

def wrap(a):
    while a>180: a-=360
    while a<-180: a+=360
    return a

def clamp(x,a):
    return max(-a,min(a,x))

def control(obs):
    global mode,phi_f,look,look_t,cnt
    cnt+=1
    dt=obs.get('dt',0.1) or 0.1
    t=obs.get('t',0.0)
    v=obs['motion']['v_mps']
    st=math.radians(obs['steer_deg'])
    X,Y,P=pose
    ds=v*dt
    X+=ds*math.cos(P); Y+=ds*math.sin(P); P+=ds*math.tan(st)/1.25
    pose[0]=X; pose[1]=Y; pose[2]=P
    c=math.cos(P); s=math.sin(P)
    for name,vw in (obs.get('views') or {}).items():
        try:
            ox,oy=vw['origin']
            for b,d in vw.get('walls',[]):
                br=math.radians(b)
                x=ox+d*math.cos(br); y=oy+d*math.sin(br)
                wx=X+x*c-y*s; wy=Y+x*s+y*c
                pts[(round(wx*10),round(wy*10))]=(wx,wy,t)
        except Exception:
            pass
    if len(pts)>2500:
        items=sorted(pts.items(),key=lambda kv:kv[1][2])
        for k,_ in items[:500]: del pts[k]
    loc=[]
    for (wx,wy,tt) in pts.values():
        dx=wx-X; dy=wy-Y
        x=dx*c+dy*s; y=-dx*s+dy*c
        if x*x+y*y<81: loc.append((x,y))
    h=obs['hitch_deg']
    rig=obs['rig']
    Rx,Ry=rig['trailer_rear']
    rear=180.0-h
    # gaze
    if t-look_t>2.5:
        look=-look; look_t=t
    # mode
    if obs.get('status')=='JACKKNIFED' or abs(h)>38:
        mode='fwd'
    if mode=='fwd' and abs(h)<6:
        mode='rev'
    if mode=='fwd':
        return (0.0,0.6,look)
    # target
    tgt=obs.get('target') or {}
    tdir=None
    if tgt.get('in_sight') and tgt.get('bearing_deg') is not None:
        eye=rig['eye']; tb=math.radians(tgt['bearing_deg']); td=tgt.get('dist_m',3.0)
        tx=eye[0]+td*math.cos(tb); ty=eye[1]+td*math.sin(tb)
        tdir=math.degrees(math.atan2(ty-Ry,tx-Rx))
    best=None; bests=-1e9; bestfree=0
    for k in range(-12,13):
        phi=rear+k*5.0
        u=math.radians(phi); ux=math.cos(u); uy=math.sin(u)
        free=5.0; clr=1.5
        for (x,y) in loc:
            dx=x-Rx; dy=y-Ry
            al=dx*ux+dy*uy
            if al<=-0.2: continue
            lat=abs(-dx*uy+dy*ux)
            if lat<0.75 and al<free: free=max(al,0.0)
            if al<3.0:
                cl=lat-0.475
                if cl<clr: clr=cl
        sc=min(free,4.0)+0.6*max(min(clr,1.2),-0.5)-0.012*abs(k*5.0)
        if phi_f is not None: sc-=0.006*abs(wrap(phi-phi_f))
        if tdir is not None: sc-=0.015*abs(wrap(phi-tdir))
        if sc>bests: bests=sc; best=phi; bestfree=free
    if phi_f is None: phi_f=best
    else: phi_f=phi_f+0.4*wrap(best-phi_f)
    err=wrap(phi_f-rear)
    hd=clamp(-0.9*err,25.0)
    steer=clamp(2.5*(h-hd),45.0)
    spd=-0.55
    if bestfree<1.0: spd=-0.35
    if cnt%20==0:
        print('t%.1f h%.1f rear%.0f phi%.0f free%.1f hd%.0f st%.0f n%d tgt%s'%(t,h,rear,phi_f,bestfree,hd,steer,len(loc),tdir))
    return (steer,spd,look)

